using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;
internal sealed class OnboardingDraft {
 internal Settings Settings;internal List<LaunchMode> Modes;internal bool Startup;internal string AudioSource="";
}
internal static class Onboarding {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024};
 internal static bool ShouldShow(Settings settings){return !settings.Configured&&!settings.OnboardingDeferred;}
 internal static OnboardingDraft Draft(Store store,bool startup){return new OnboardingDraft{Settings=Json.Deserialize<Settings>(Json.Serialize(store.Value.settings)),Modes=store.Value.modes.Select(LaunchModes.Clone).ToList(),Startup=startup};}
 internal static void Validate(OnboardingDraft draft){var s=draft.Settings;if(String.IsNullOrWhiteSpace(s.DisplayName)||s.DisplayName.Length>40||String.IsNullOrWhiteSpace(s.AppTitle)||s.AppTitle.Length>22)throw new InvalidDataException("Indiquez votre prénom et un nom d’espace (22 caractères maximum).");if(s.Projects==null||s.Projects.Count<1||s.Projects.Count>30||s.Projects.Any(p=>String.IsNullOrWhiteSpace(p)||p.Length>80))throw new InvalidDataException("Indiquez entre 1 et 30 projets, de 80 caractères au maximum.");Store.Validate(new Data{settings=s,modes=draft.Modes});}
 internal static bool Commit(Store store,OnboardingDraft draft,Func<bool> save){Validate(draft);var oldSettings=store.Value.settings;var oldModes=store.Value.modes;bool replaceAudio=!String.IsNullOrEmpty(draft.AudioSource)&&!Path.GetFullPath(draft.AudioSource).Equals(Path.GetFullPath(store.AudioPath),StringComparison.OrdinalIgnoreCase);bool hadAudio=File.Exists(store.AudioPath);string rollback=Path.Combine(store.Root,".onboarding-audio-"+Guid.NewGuid().ToString("N"));bool changedAudio=false,committed=false;try{if(replaceAudio){if(hadAudio)File.Copy(store.AudioPath,rollback);store.SetAudio(draft.AudioSource);changedAudio=true;}draft.Settings.Configured=true;draft.Settings.OnboardingDeferred=false;store.Value.settings=draft.Settings;store.Value.modes=draft.Modes;if(save()){committed=true;return true;}return false;}finally{if(!committed){store.Value.settings=oldSettings;store.Value.modes=oldModes;if(changedAudio){if(hadAudio)File.Copy(rollback,store.AudioPath,true);else if(File.Exists(store.AudioPath))File.Delete(store.AudioPath);}}if(File.Exists(rollback))File.Delete(rollback);}}
 internal static void ValidateLocal(Settings s){if(s.LocalShortcuts==null)s.LocalShortcuts=new List<ModeAction>();if(s.LocalShortcuts.Count>30)throw new InvalidDataException("Limite : 30 raccourcis d’applications et de dossiers.");foreach(var action in s.LocalShortcuts){LaunchModes.ValidateAction(action);if(action.kind!="exe"&&action.kind!="folder")throw new InvalidDataException("Un raccourci local doit désigner une application ou un dossier.");}}
 internal static void Test(string folder){var store=new Store(Path.Combine(folder,"onboarding"));if(!ShouldShow(store.Value.settings))throw new Exception("Premier lancement absent");var draft=Draft(store,false);draft.Settings.DisplayName="Autre utilisateur";draft.Settings.AppTitle="Mon bureau";draft.Settings.LocalShortcuts.Add(new ModeAction{kind="folder",label="Mes fichiers",target=Path.GetFullPath(folder)});draft.Settings.Appearance=Appearance.Presets().Last();draft.Settings.HomeBlocks[0].visible=false;draft.Modes.Add(new LaunchMode{id="new",name="Personnel",actions=new List<ModeAction>{new ModeAction{kind="discord",label="Discord"}}});if(store.Value.settings.DisplayName!=""||store.Value.modes.Count!=0)throw new Exception("Assistant modifie les données avant validation");string mp3=Path.Combine(store.Root,"chosen.mp3");File.WriteAllText(mp3,"new-audio");File.WriteAllText(store.AudioPath,"old-audio");draft.AudioSource=mp3;if(Commit(store,draft,()=>false)||store.Value.settings.Configured||File.ReadAllText(store.AudioPath)!="old-audio")throw new Exception("Retour arrière de l’assistant");if(!Commit(store,draft,delegate{store.Save();return true;}))throw new Exception("Assistant non enregistré");store=new Store(store.Root);if(ShouldShow(store.Value.settings)||store.Value.settings.DisplayName!="Autre utilisateur"||store.Value.settings.EnableBotModule||store.Value.settings.LocalShortcuts.Count!=1||store.Value.modes.Count!=1||File.ReadAllText(store.AudioPath)!="new-audio")throw new Exception("Persistance de l’assistant");store.Value.settings.OnboardingDeferred=true;store.Value.settings.Configured=false;if(ShouldShow(store.Value.settings))throw new Exception("Assistant différé réaffiché");}
}
